import{_ as p,a0 as o,w as l,s as d,ao as c,I as t,x as i,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中將文件編碼轉換為 UTF-8 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中將文件編碼轉換為 UTF-8 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中將文件編碼轉換為 UTF-8 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中將文件編碼轉換為 UTF-8 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161102 How to Convert Files to UTF-8 Encoding in Linux","title":"如何在 Linux 中將文件編碼轉換為 UTF-8","tag":"201611","desc":""},"relativePath":"201611/20161102 How to Convert Files to UTF-8 Encoding in Linux.md","filePath":"[post].md"}'),r={name:"201611/20161102 How to Convert Files to UTF-8 Encoding in Linux.md"};function h(u,s,g,k,f,b){const n=o("Link");return l(),d("div",null,[s[13]||(s[13]=c(`<h1 id="如何在-linux-中將文件編碼轉換為-utf-8" tabindex="-1">如何在 Linux 中將文件編碼轉換為 UTF-8 <a class="header-anchor" href="#如何在-linux-中將文件編碼轉換為-utf-8" aria-label="Permalink to “如何在 Linux 中將文件編碼轉換為 UTF-8”">​</a></h1><p>在這篇教程中，我們將解釋字符編碼的含義，然後給出一些使用命令列工具將使用某種字符編碼的文件轉化為另一種編碼的例子。最後，我們將一起看一看如何在 Linux 下將使用各種字符編碼的文件轉化為 UTF-8 編碼。</p><p>你可能已經知道，計算機除了二進制數據，是不會理解和存儲字符、數字或者任何人類能夠理解的東西的。一個二進制位只有兩種可能的值，也就是 <code>0</code> 或 <code>1</code>，<code>真</code>或<code>假</code>，<code>是</code>或<code>否</code>。其它的任何事物，比如字符、數據和圖片，必須要以二進制的形式來表現，以供計算機處理。</p><p>簡單來説，字符編碼是一種可以指示電腦來將原始的 0 和 1 解釋成實際字符的方式，在這些字符編碼中，字符都以一串數字來表示。</p><p>字符編碼方案有很多種，比如 ASCII、ANCI、Unicode 等等。下面是 ASCII 編碼的一個例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>字符            二進制</span></span>
<span class="line"><span>A               01000001</span></span>
<span class="line"><span>B               01000010</span></span></code></pre></div><p>在 Linux 中，命令列工具 <code>iconv</code> 用來將使用一種編碼的文本轉化為另一種編碼。</p><p>你可以使用 <code>file</code> 命令，並添加 <code>-i</code> 或 <code>--mime</code> 參數來查看一個文件的字符編碼，這個參數可以讓程序像下面的例子一樣輸出字符串的 mime (Multipurpose Internet Mail Extensions) 數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file -i Car.java</span></span>
<span class="line"><span>$ file -i CarDriver.java</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/10/Check-File-Encoding-in-Linux.png" alt="在 Linux 中查看文件的編碼"></p><p><em>在 Linux 中查看文件的編碼</em></p><p>iconv 工具的使用方法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iconv option</span></span>
<span class="line"><span>$ iconv options -f from-encoding -t to-encoding inputfile(s) -o outputfile</span></span></code></pre></div><p>在這裏，<code>-f</code> 或 <code>--from-code</code> 表明了輸入編碼，而 <code>-t</code> 或 <code>--to-encoding</code> 指定了輸出編碼。</p><p>為了列出所有已有編碼的字符集，你可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iconv -l</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/10/List-Coded-Charsets-in-Linux.png" alt="列出所有已有編碼字符集"></p><p><em>列出所有已有編碼字符集</em></p><h3 id="將文件從-iso-8859-1-編碼轉換為-utf-8-編碼" tabindex="-1">將文件從 ISO-8859-1 編碼轉換為 UTF-8 編碼 <a class="header-anchor" href="#將文件從-iso-8859-1-編碼轉換為-utf-8-編碼" aria-label="Permalink to “將文件從 ISO-8859-1 編碼轉換為 UTF-8 編碼”">​</a></h3><p>下面，我們將學習如何將一種編碼方案轉換為另一種編碼方案。下面的命令將會將 ISO-8859-1 編碼轉換為 UTF-8 編碼。</p><p>考慮如下文件 <code>input.file</code>，其中包含這幾個字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>� � � �</span></span></code></pre></div><p>我們從查看這個文件的編碼開始，然後來查看文件內容。最後，我們可以把所有字符轉換為 UTF-8 編碼。</p><p>在運行 <code>iconv</code> 命令之後，我們可以像下面這樣檢查輸出文件的內容，和它使用的字符編碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file -i input.file</span></span>
<span class="line"><span>$ cat input.file </span></span>
<span class="line"><span>$ iconv -f ISO-8859-1 -t UTF-8//TRANSLIT input.file -o out.file</span></span>
<span class="line"><span>$ cat out.file </span></span>
<span class="line"><span>$ file -i out.file</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/10/Converts-UTF8-to-ASCII-in-Linux.png" alt="在 Linux 中將 ISO-8859-1 轉化為 UTF-8"></p><p><em>在 Linux 中將 ISO-8859-1 轉化為 UTF-8</em></p><p>注意：如果輸出編碼後面添加了 <code>//IGNORE</code> 字符串，那些不能被轉換的字符將不會被轉換，並且在轉換後，程序會顯示一條錯誤信息。</p><p>好，如果字符串 <code>//TRANSLIT</code> 被添加到了上面例子中的輸出編碼之後 (<code>UTF-8//TRANSLIT</code>)，待轉換的字符會盡量採用形譯原則。也就是説，如果某個字符在輸出編碼方案中不能被表示的話，它將會被替換為一個形狀比較相似的字符。</p><p>而且，如果一個字符不在輸出編碼中，而且不能被形譯，它將會在輸出文件中被一個問號標記 <code>?</code> 代替。</p><h3 id="將多個文件轉換為-utf-8-編碼" tabindex="-1">將多個文件轉換為 UTF-8 編碼 <a class="header-anchor" href="#將多個文件轉換為-utf-8-編碼" aria-label="Permalink to “將多個文件轉換為 UTF-8 編碼”">​</a></h3><p>回到我們的主題。如果你想將多個文件甚至某目錄下所有文件轉化為 UTF-8 編碼，你可以像下面一樣，編寫一個簡單的 shell 腳本，並將其命名為 <code>encoding.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>### 將 values_here 替換為輸入編碼</span></span>
<span class="line"><span>FROM_ENCODING=&quot;value_here&quot;</span></span>
<span class="line"><span>### 輸出編碼 (UTF-8)</span></span>
<span class="line"><span>TO_ENCODING=&quot;UTF-8&quot;</span></span>
<span class="line"><span>### 轉換命令</span></span>
<span class="line"><span>CONVERT=&quot; iconv  -f   $FROM_ENCODING  -t   $TO_ENCODING&quot;</span></span>
<span class="line"><span>### 使用循環轉換多個文件</span></span>
<span class="line"><span>for  file  in  *.txt; do</span></span>
<span class="line"><span>$CONVERT   &quot;$file&quot;   -o  &quot;\${file%.txt}.utf8.converted&quot;</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p>保存文件，然後為它添加可執行權限。在待轉換文件 (*.txt) 所在的目錄中運行這個腳本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod  +x  encoding.sh</span></span>
<span class="line"><span>$ ./encoding.sh</span></span></code></pre></div><p>重要事項：你也可以使這個腳本變得更通用，比如轉換任意特定的字符編碼到另一種編碼。為了達到這個目的，你只需要改變 <code>FROM_ENCODING</code> 及 <code>TO_ENCODING</code> 變量的值。別忘了改一下輸出文件的文件名 <code>&quot;\${file%.txt}.utf8.converted&quot;</code>.</p><p>若要了解更多信息，可以查看 <code>iconv</code> 的手冊頁 (man page)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man iconv</span></span></code></pre></div><p>將這篇指南總結一下，理解字符編碼的概念、瞭解如何將一種編碼方案轉換為另一種，是一個電腦用户處理文本時必須要掌握的知識，程序員更甚。</p><p>最後，你可以在下面的評論部分中與我們聯繫，提出問題或反饋。</p><hr>`,41)),t("p",null,[s[1]||(s[1]=i("via: ",-1)),e(n,{href:"http://www.tecmint.com/convert-files-to-utf-8-encoding-in-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("http://www.tecmint.com/convert-files-to-utf-8-encoding-in-linux/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=i("作者：",-1)),e(n,{href:"http://www.tecmint.com/author/aaronkili/"},{default:a(()=>[...s[2]||(s[2]=[i("Aaron Kili",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),e(n,{href:"https://github.com/StdioA"},{default:a(()=>[...s[3]||(s[3]=[i("StdioA",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:a(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:a(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const C=p(r,[["render",h]]);export{x as __pageData,C as default};
